import{_ as e,o as a,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const m=JSON.parse('{"title":"Unreal Engineと標準C++をつなぐ学習ガイド","description":"","frontmatter":{"title":"Unreal Engineと標準C++をつなぐ学習ガイド","study":{"source":"C++ Wiki","status":"published","summary":"標準C++の仕組みと、UObject・GC・リフレクション・UBTの対応を順に読む。","section":"learning","format":"path","domain":"game","collection":"cpp-design","order":10}},"headers":[],"relativePath":"game/unreal/index.md","filePath":"game/unreal/index.md"}'),d={name:"game/unreal/index.md"};function l(i,t,o,s,c,u){return a(),r("div",null,[...t[0]||(t[0]=[n('<div id="第10部-unreal-engineとの対応" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="unreal-engineと標準c-をつなぐ学習ガイド" tabindex="-1">Unreal Engineと標準C++をつなぐ学習ガイド <a class="header-anchor" href="#unreal-engineと標準c-をつなぐ学習ガイド" aria-label="Permalink to &quot;Unreal Engineと標準C++をつなぐ学習ガイド&quot;">​</a></h1><p>UEのC++は「標準C++の上に、<strong>エンジン独自の層</strong>(リフレクション・GC・独自コンテナ・ビルドツール)を被せたもの」です。このガイドから読む各本文では「<strong>標準C++ではどう書くか</strong>」と「<strong>UEではなぜ独自の方法を使うか</strong>」を対比します。UE独自仕様を標準C++と混同しないことが、両方を正しく学ぶ鍵です。</p><h2 id="本文を読む順序" tabindex="-1">本文を読む順序 <a class="header-anchor" href="#本文を読む順序" aria-label="Permalink to &quot;本文を読む順序&quot;">​</a></h2><ol><li><a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponent</a></li><li><a href="/study/game/unreal/gc-and-object-pointers.html">UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr</a></li><li><a href="/study/game/unreal/reflection-and-uht.html">リフレクション: UCLASS・UFUNCTION・Unreal Header Tool</a></li><li><a href="/study/game/unreal/build-system-ubt.html">Unreal Build Tool・Module・Build.cs・Target.cs</a></li><li><a href="/study/game/unreal/smart-pointers.html">UEのスマートポインタ: TSharedPtr・TUniquePtr・TSoftObjectPtr</a></li><li><a href="/study/game/unreal/delegates-and-interfaces.html">UEの Delegate と Interface</a></li><li><a href="/study/game/unreal/gameplay-framework.html">Gameplay Framework・Subsystem・Slate/UMG・DataAsset/DataTable</a></li></ol><p>仕組みを確認したら、「実践・サンプル」の<a href="/study/game/unreal/exercises.html">Unreal Engine演習</a>で確かめられます。</p><h2 id="全体対応表" tabindex="-1">全体対応表 <a class="header-anchor" href="#全体対応表" aria-label="Permalink to &quot;全体対応表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>領域</th><th>標準C++</th><th>UE</th></tr></thead><tbody><tr><td>基底オブジェクト</td><td>なし(自由)</td><td>UObject(リフレクション+GCの世界)</td></tr><tr><td>メモリ管理</td><td>RAII+スマートポインタ</td><td>UObject層=GC / 非UObject層=標準流 <strong>2層構造</strong></td></tr><tr><td>型情報</td><td>RTTI(最小限)</td><td>自作リフレクション(UCLASS等+UHT生成コード)</td></tr><tr><td>コンテナ</td><td>std::vector, std::string...</td><td>TArray, FString...(独自。理由は本文)</td></tr><tr><td>ビルド</td><td>CMake等</td><td>UBT+Build.cs/Target.cs</td></tr><tr><td>イベント</td><td>自作(std::function)</td><td>Delegateマクロ群(+Blueprint連携)</td></tr><tr><td>例外</td><td>選択制</td><td><strong>非使用</strong>(check/ensure文化)</td></tr></tbody></table><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><p><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a>、<a href="/study/runtime/memory/ownership-and-borrowing.html">所有権</a>、<a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位</a>を先に読むと、「UEがなぜそうしたか」が理解できます。</p><hr><p><a href="/study/guide/cpp-index.html">C++・設計の学習ガイド</a> | <a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponentの本文</a></p>',12)])])}const g=e(d,[["render",l]]);export{m as __pageData,g as default};
